// === BUILD TIME: scripts/gen-neural-sign.mjs (space colonization, the core) ===
import { createCanvas } from '@napi-rs/canvas';
import KDBush from 'kdbush';
const SEG = 4, ATTRACT = 24, KILL = 6;
function growLine(text, fontPx) {
  const W = text.length * fontPx * 0.75, H = fontPx * 1.4;
  const cv = createCanvas(W, H), ctx = cv.getContext('2d');
  ctx.font = `900 ${fontPx}px Inter`; ctx.fillStyle = '#fff';
  ctx.fillText(text, 0, fontPx);
  const px = ctx.getImageData(0, 0, W, H).data;
  const inside = [], outline = [];
  for (let y = 0; y < H; y += 3) for (let x = 0; x < W; x += 3) {
    const a = px[(y * W + x) * 4 + 3] > 128;
    if (a) { inside.push({ x, y });
      // outline test: any 4-neighbor empty
      const nb = i => px[i * 4 + 3] <= 128;
      if (nb((y*W)+x+1)||nb((y*W)+x-1)||nb(((y+1)*W)+x)||nb(((y-1)*W)+x)) outline.push({x,y}); }
  }
  // attractors = inside pixels + sparse halo just outside (outward tendrils)
  let attractors = inside.slice();
  for (const o of outline) if (Math.random() < 0.15)
    attractors.push({ x: o.x + (Math.random()-0.5)*30, y: o.y + (Math.random()-0.5)*30 });
  // roots: lowest inside-pixel per x-band -> letter stems
  const nodes = [];
  const bands = {};
  for (const p of inside) { const b = (p.x/20)|0; if (!bands[b] || p.y > bands[b].y) bands[b] = p; }
  for (const k in bands) nodes.push({ x: bands[k].x, y: bands[k].y, parent: -1, w: 1 });
  // grow
  for (let it = 0; it < 400 && attractors.length; it++) {
    const idx = new KDBush(nodes.length); for (const n of nodes) idx.add(n.x, n.y); idx.finish();
    const inf = nodes.map(() => []);
    for (const a of attractors) {
      let best = -1, bd = ATTRACT * ATTRACT;
      for (const id of idx.within(a.x, a.y, ATTRACT)) {
        const d = (nodes[id].x-a.x)**2 + (nodes[id].y-a.y)**2; if (d < bd) { bd = d; best = id; } }
      if (best >= 0) inf[best].push(a);
    }
    const fresh = [];
    nodes.forEach((n, i) => {
      if (!inf[i].length) return;
      let dx = 0, dy = 0; for (const a of inf[i]) { dx += a.x-n.x; dy += a.y-n.y; }
      const L = Math.hypot(dx, dy) || 1;
      fresh.push({ x: n.x + SEG*dx/L + (Math.random()-0.5),
                   y: n.y + SEG*dy/L + (Math.random()-0.5), parent: i, w: 1 });
    });
    const before = nodes.length; nodes.push(...fresh);
    attractors = attractors.filter(a => !nodes.some((n, i) => i >= before-200 &&
      (n.x-a.x)**2 + (n.y-a.y)**2 < KILL*KILL));
  }
  // thickness via descendant count
  for (let i = nodes.length-1; i > 0; i--) if (nodes[i].parent >= 0)
    nodes[nodes[i].parent].w += nodes[i].w * 0.06;
  return { nodes };
}
